package app.strata3d.model

import org.junit.Assert.fail
import org.junit.Assume.assumeTrue
import org.junit.Test
import java.io.File
import java.io.IOException
import kotlin.math.abs
import kotlin.math.max

/**
 * Parses every model in `test-models/` (generated by `tools/generate_test_models.py`) with the real
 * [ModelParser] and compares the triangle count and bounding box against `expected.json`, which the
 * generator computes independently of the app's code.
 *
 * A readable report is printed and written to `app/build/reports/test-models.txt`.
 */
class TestModelsTest {

    private data class Result(val file: String, val tier: String, val status: String, val detail: String)

    @Test
    fun allTestModelsParseAsExpected() {
        val dir = File(System.getProperty("strata.testModelsDir") ?: "../test-models")
        val manifest = File(dir, "expected.json")
        assumeTrue("test-models/expected.json not found; run tools/generate_test_models.py", manifest.exists())

        val models = JsonParser.parse(manifest.readText()).get("models").asList().orEmpty()
        val results = models.map { check(dir, it) }

        val report = buildString {
            appendLine("Strata:3D test-model report (${results.size} models)")
            appendLine("%-6s %-11s %-50s %s".format("RESULT", "TIER", "FILE", "DETAIL"))
            results.forEach { appendLine("%-6s %-11s %-50s %s".format(it.status, it.tier, it.file, it.detail)) }
            val failed = results.count { it.status != "PASS" }
            appendLine()
            appendLine("${results.size - failed} passed, $failed failed")
        }
        println(report)
        File("build/reports").apply { mkdirs() }.resolve("test-models.txt").writeText(report)

        val failures = results.filter { it.status != "PASS" }
        if (failures.isNotEmpty()) {
            fail("${failures.size} test model(s) did not parse as expected:\n" +
                failures.joinToString("\n") { "  [${it.tier}] ${it.file}: ${it.detail}" })
        }
    }

    private fun check(dir: File, entry: JsonValue): Result {
        val name = entry.get("file").asString()!!
        val tier = entry.get("tier").asString() ?: "?"
        val expectError = entry.get("expect").asString() == "error"
        val file = File(dir, name)

        // Companion files (e.g. a glTF's .bin) come from the model's folder, like picking them together in the app.
        val resources = ModelResources { uri ->
            File(file.parentFile, ModelResources.normalize(uri)).takeIf { it.isFile }?.inputStream()
        }
        val started = System.nanoTime()
        val mesh = try {
            file.inputStream().use { ModelParser.parse(it, file.name, file.length(), resources) }
        } catch (e: ModelParseException) {
            return if (expectError) Result(name, tier, "PASS", "clear error: ${e.message}")
            else Result(name, tier, "FAIL", "rejected a valid file: ${e.message}")
        } catch (e: IOException) {
            return if (expectError) Result(name, tier, "PASS", "I/O error: ${e.message}")
            else Result(name, tier, "FAIL", "I/O error on a valid file: ${e.message}")
        } catch (e: Throwable) {
            // Anything else would reach the user as a confusing message (or crash the app).
            return Result(name, tier, "FAIL", "unexpected ${e.javaClass.simpleName}: ${e.message}")
        }
        val ms = (System.nanoTime() - started) / 1_000_000

        if (expectError) {
            return Result(name, tier, "FAIL", "should have been rejected, but produced ${mesh.triangleCount} triangles")
        }

        val expectedTris = entry.get("triangles").asInt()!!
        val fileBox = entry.get("bbox").asFloatArray()!!
        // expected.json gives glTF bounds in the file's own frame (+Y up); the app shows glTF upright (+Z up):
        // (x, y, z) -> (x, -z, y).
        val gltf = name.contains("gltf", ignoreCase = true) || name.endsWith(".glb", true)   // also a glTF inside a .zip
        val expectedBox = if (!gltf) fileBox else floatArrayOf(fileBox[0], -fileBox[5], fileBox[1], fileBox[3], -fileBox[2], fileBox[4])
        val b = mesh.bounds
        val actualBox = floatArrayOf(b.minX, b.minY, b.minZ, b.maxX, b.maxY, b.maxZ)
        val extent = max(max(expectedBox[3] - expectedBox[0], expectedBox[4] - expectedBox[1]), expectedBox[5] - expectedBox[2])
        val tolerance = max(1e-3f, extent * 1e-4f)
        val boxOk = expectedBox.indices.all { abs(expectedBox[it] - actualBox[it]) <= tolerance }

        // Surface area catches wrong connectivity (e.g. mis-decoded indices) that count + bounds alone would miss.
        val expectedArea = entry.get("surface_area").asDouble()
        val areaOk = expectedArea == null ||
            abs(mesh.stats.surfaceArea - expectedArea) <= max(1e-6, expectedArea * 1e-3)

        return when {
            mesh.triangleCount != expectedTris ->
                Result(name, tier, "FAIL", "triangles ${mesh.triangleCount}, expected $expectedTris")
            !boxOk ->
                Result(name, tier, "FAIL", "bounds ${actualBox.fmt()}, expected ${expectedBox.fmt()}")
            !areaOk ->
                Result(name, tier, "FAIL", "surface area ${"%.3f".format(mesh.stats.surfaceArea)}, expected ${"%.3f".format(expectedArea)}")
            else -> Result(name, tier, "PASS", "$expectedTris triangles, bounds + area match (${ms} ms)")
        }
    }

    private fun FloatArray.fmt() = joinToString(prefix = "[", postfix = "]") { "%.3f".format(it) }
}
